checks = r'''
package tv.orbit.shield

import java.io.ByteArrayOutputStream
import java.io.File
import java.io.IOException
import java.nio.channels.FileChannel
import java.nio.file.StandardOpenOption.READ
import java.util.concurrent.CancellationException
import org.apache.commons.compress.archivers.sevenz.SevenZArchiveEntry
import org.apache.commons.compress.archivers.sevenz.SevenZOutputFile

fun main(args: Array<String>) {
    val file = File(args.single(), "solid.7z")
    val original = file.readBytes()
    val cue = "FILE \"Track01.bin\" BINARY\n".toByteArray()
    val track = ByteArray(81920) { it.toByte() }
    val expected = mapOf("Disc/Game.cue" to cue, "Disc/Track01.bin" to track, "Disc/Empty.txt" to byteArrayOf())
    val sink = mutableMapOf<String, ByteArray>()
    val opened = mutableListOf<String>()
    val directories = mutableSetOf<String>()
    val completed = mutableSetOf<String>()
    fun output(path: String) = object : ByteArrayOutputStream() {
        init { opened += path }
        override fun close() { sink[path] = toByteArray() }
    }
    lateinit var plan: GameArchivePlan
    FileChannel.open(file.toPath(), READ).use { channel ->
        channel.position(4)
        check(GameArchiveFormat.detect(channel) == GameArchiveFormat.SEVEN_Z && channel.position() == 4L)
        check(GameArchiveFormat.supportsName("PS1.7Z") && GameArchiveFormat.supportsName("PS1.ZIP"))
        check(!GameArchiveFormat.supportsName("PS1.7z.002"))
        plan = GameSevenZArchive.inspect(channel) {}
        check(channel.isOpen)
        check(plan.fileCount == expected.size && plan.totalBytes == expected.values.sumOf { it.size.toLong() })
        check(plan.sourceMetadata?.length == 64)
        val interrupted = runCatching {
            GameSevenZArchive.extract(channel, plan, directories::add, ::output,
                onFileCompleted = { completed += it.path; throw CancellationException("pause") })
        }
        check(interrupted.exceptionOrNull() is CancellationException)
        val saved = completed.single()
        check(sink.getValue(saved).contentEquals(expected.getValue(saved)))
        opened.clear()
        val progress = mutableListOf<Long>()
        GameSevenZArchive.extract(channel, plan, directories::add, ::output, onProgress = progress::add,
            completed = { it.path in completed }, onFileCompleted = { completed += it.path })
        check(channel.isOpen && saved !in opened && completed == expected.keys)
        check(sink.keys == expected.keys && expected.all { (path, bytes) -> sink.getValue(path).contentEquals(bytes) })
        check("Disc" in directories && progress.first() == 0L && progress.last() == plan.totalBytes)
        check(progress.zipWithNext().all { (previous, next) -> previous <= next })
        val writes = opened.size
        check(runCatching {
            GameSevenZArchive.extract(channel, plan.copy(sourceMetadata = "stale"), {}, ::output)
        }.isFailure && opened.size == writes)
    }
    check(file.readBytes().contentEquals(original))
    val broken = File(file.parent, "invalid-header.7z")
    broken.writeBytes(original.copyOf().apply { this[lastIndex] = (this[lastIndex].toInt() xor 1).toByte() })
    FileChannel.open(broken.toPath(), READ).use { channel ->
        check(runCatching { GameSevenZArchive.inspect(channel) {} }.exceptionOrNull() is IOException)
        check(channel.isOpen)
    }
    fun makeArchive(filename: String, member: String): File = File(file.parent, filename).also { target ->
        SevenZOutputFile(target).use { out ->
            out.putArchiveEntry(SevenZArchiveEntry().apply { name = member })
            out.write(byteArrayOf(1, 2, 3))
            out.closeArchiveEntry()
        }
    }
    FileChannel.open(makeArchive("raw.7z", "Game.sfc").toPath(), READ).use { input ->
        val raw = GameSevenZArchive.inspect(input) {}
        check(raw.entries.single().path == "Game.sfc")
        check(gameArchiveFingerprint(raw) != gameArchiveFingerprint(plan))
    }
    FileChannel.open(makeArchive("traversal.7z", "../escape.sfc").toPath(), READ).use { input ->
        check(runCatching { GameSevenZArchive.inspect(input) {} }.isFailure)
    }
    println("PASS 7z: encoded solid and raw headers, CUE/BIN/empty bytes, checked resume, stable source and channel, corruption and path rejection")
}
'''

app = ROOT / 'native-launcher/app/src/main/java/tv/orbit/shield'
classpath = ':'.join(str(p) for p in [
    COMPILER[1], jar('org.apache.commons', 'commons-compress', '1.28.0'),
    jar('org.tukaani', 'xz', '1.10'), jar('commons-codec', 'commons-codec', '1.19.0'),
    jar('commons-io', 'commons-io', '2.20.0'), jar('org.apache.commons', 'commons-lang3', '3.18.0'),
])
with tempfile.TemporaryDirectory(prefix='gostex-7z-') as temporary:
    folder = Path(temporary)
    (folder / 'solid.7z').write_bytes(solid)
    source = folder / 'Checks.kt'
    source.write_text(checks)
    classes = folder / 'classes'
    subprocess.run([str(JAVA), '-cp', ':'.join(map(str, COMPILER)), 'org.jetbrains.kotlin.cli.jvm.K2JVMCompiler',
                    '-no-stdlib', '-no-reflect', '-classpath', classpath, '-d', str(classes), str(source),
                    *[str(app / name) for name in ('TorrDownloadPaths.kt', 'GameArchivePlan.kt', 'GameSevenZHeader.kt',
                                                   'GameSevenZArchive.kt')]], check=True)
    subprocess.run([str(JAVA), '-cp', f'{classes}:{classpath}', 'tv.orbit.shield.ChecksKt', str(folder)], check=True)
